class Solution {
public:
    // 解析形如 "list:[1,4,5]" 的链表描述字符串
    ListNode* parseList(const string& s) {
        size_t p = s.find('[');
        size_t q = s.find(']');
        if (p == string::npos || q == string::npos || q <= p) return nullptr;
        string body = s.substr(p + 1, q - p - 1);
        ListNode dummy(0);
        ListNode* cur = &dummy;
        stringstream ss(body);
        string tok;
        while (getline(ss, tok, ',')) {
            size_t a = tok.find_first_not_of(" \t");
            if (a == string::npos) continue;
            tok = tok.substr(a);
            if (tok.empty()) continue;
            cur->next = new ListNode(stoi(tok));
            cur = cur->next;
        }
        return dummy.next;
    }

    ListNode* mergeKLists(vector<string> lists) {
        // 小顶堆：堆顶始终是所有链表头中的最小节点
        auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };
        priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);
        for (const auto& s : lists) {
            ListNode* h = parseList(s);
            if (h) pq.push(h);
        }
        ListNode dummy(0);
        ListNode* cur = &dummy;
        while (!pq.empty()) {
            ListNode* node = pq.top();
            pq.pop();
            cur->next = node;
            cur = cur->next;
            if (node->next) pq.push(node->next);
        }
        return dummy.next;
    }
};

