public:
    list<pair<int, int>> q;
    unordered_map<int, list<pair<int, int>>::iterator> m;
    int cap;

    LRUCache(int capacity) { cap = capacity; }

    int get(int key) {
        if (!m.count(key)) return -1;
        auto it = m[key];
        int v = it->second;
        q.erase(it);
        q.push_front({key, v});
        m[key] = q.begin();
        return v;
    }

    void put(int key, int value) {
        if (m.count(key)) q.erase(m[key]);
        q.push_front({key, value});
        m[key] = q.begin();
        if ((int)q.size() > cap) {
            m.erase(q.back().first);
            q.pop_back();
        }
    }
};

